abel><input type="url" name="facebook_url" value="{{ old('facebook_url',$settings['facebook_url']) }}" placeholder="https://facebook.com/..."></div><div class="field"><label>LinkedIn URL</label><input type="url" name="linkedin_url" value="{{ old('linkedin_url',$settings['linkedin_url']) }}" placeholder="https://linkedin.com/company/..."></div><div class="field"><label>Instagram URL</label><input type="url" name="instagram_url" value="{{ old('instagram_url',$settings['instagram_url']) }}" placeholder="https://instagram.com/..."></div><div class="field"><label>YouTube URL</label><input type="url" name="youtube_url" value="{{ old('youtube_url',$settings['youtube_url']) }}" placeholder="https://youtube.com/@..."></div><p class="muted full">Social icons appear in the footer only for the links you fill in.</p><div class="full"><button class="button">Save page settings</button></div></form></section>
